rss.channel:
dryline: Tahoe trail conditions
{{ site_url }}

Daily cited trail conditions for Lake Tahoe and Truckee. Not safety advice.
en-us
{{ built_at }}
{% for day, lines, counts in items %}


{{ day.strftime("%a %b %-d") }}: {{ counts }}
{{ site_url }}archive/{{ day }}/
{{ site_url }}archive/{{ day }}/
{{ rfc822(day) }}
<ul>{% for line in lines %}<li><strong>{{ line.trail_name }}: {{ LABEL[line.status] }}.</strong> {% if line.status == "unknown" %}Missing: {{ line.missing[0].what }}. <a href="{{ line.missing[0].tried_url }}">checked {{ line.missing[0].tried_url|host }}</a>{% else %}{% set c = line.claims[0] %}{{ c.statement }} <a href="{{ c.source_url }}">{{ c.source_url|host }}, fetched {{ c.fetched_at|stamp }}</a>{% endif %}</li>{% endfor %}</ul>

{% endfor %}
